using System.Globalization;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using SuperLiga.Api.Data;
using SuperLiga.Api.Models;
using SuperLiga.Api.Services;
namespace SuperLiga.Api.Controllers;

[ApiController, Route("api")]
public class SuperLigaController(SuperLigaDbContext db, PartidaService placar) : ControllerBase
{
    static string N(string s) => new string(s.Trim().Normalize(NormalizationForm.FormD).Where(c => CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark).ToArray()).ToUpperInvariant();
    [HttpGet("times")] public async Task<IActionResult> Times(CancellationToken ct) => Ok(await db.Times.AsNoTracking().Include(x => x.Jogadores).OrderBy(x => x.Nome).Select(x => new { x.Id, x.Nome, LogoUrl = x.Logo == null ? null : $"/api/times/{x.Id}/logo", x.Jogadores }).ToListAsync(ct));
    [HttpGet("times/{id:int}")] public async Task<IActionResult> Time(int id, CancellationToken ct) { var x = await db.Times.AsNoTracking().Where(t => t.Id == id).Select(t => new { t.Id, t.Nome, LogoUrl = t.Logo == null ? null : $"/api/times/{t.Id}/logo", Jogadores = t.Jogadores.OrderBy(j => j.NumeroCamisa).Select(j => new { j.Id, j.Nome, j.NumeroCamisa, j.Posicao }).ToList() }).SingleOrDefaultAsync(ct); return x == null ? NotFound() : Ok(x); }
    [HttpPost("times"), RequestSizeLimit(2_000_000)] public async Task<IActionResult> CriarTime([FromForm] string nome, IFormFile? logo, CancellationToken ct) { if (string.IsNullOrWhiteSpace(nome) || nome.Trim().Length > 80) return BadRequest("Nome inválido."); if (await db.Times.AnyAsync(x => x.NomeNormalizado == N(nome), ct)) return Conflict("Time já cadastrado."); if (logo is not null && (!logo.ContentType.StartsWith("image/") || logo.Length > 1_500_000)) return BadRequest("Imagem inválida ou maior que 1,5 MB."); var t = new Time { Nome = nome.Trim(), NomeNormalizado = N(nome) }; if (logo is not null) { using var m = new MemoryStream(); await logo.CopyToAsync(m, ct); t.Logo = m.ToArray(); t.LogoTipo = logo.ContentType; } db.Add(t); await db.SaveChangesAsync(ct); return Created($"/api/times/{t.Id}", new { t.Id, t.Nome }); }
    [HttpPut("times/{id:int}"), RequestSizeLimit(2_000_000)] public async Task<IActionResult> EditarTime(int id, [FromForm] string nome, IFormFile? logo, CancellationToken ct) { var t = await db.Times.FindAsync([id], ct); if (t == null) return NotFound(); if (string.IsNullOrWhiteSpace(nome) || nome.Trim().Length > 80 || await db.Times.AnyAsync(x => x.Id != id && x.NomeNormalizado == N(nome), ct)) return Conflict("Nome inválido ou duplicado."); if (logo is not null && (!logo.ContentType.StartsWith("image/") || logo.Length > 1_500_000)) return BadRequest("Imagem inválida ou maior que 1,5 MB."); t.Nome = nome.Trim(); t.NomeNormalizado = N(nome); if (logo is not null) { using var m = new MemoryStream(); await logo.CopyToAsync(m, ct); t.Logo = m.ToArray(); t.LogoTipo = logo.ContentType; } await db.SaveChangesAsync(ct); return Ok(new { t.Id, t.Nome }); }
    [HttpDelete("times/{id:int}")] public async Task<IActionResult> ExcluirTime(int id, CancellationToken ct) { var t = await db.Times.FindAsync([id], ct); if (t == null) return NotFound(); var partidas = await db.Partidas.Include(x => x.Sets).Where(x => x.TimeAId == id || x.TimeBId == id).ToListAsync(ct); db.Partidas.RemoveRange(partidas); db.Remove(t); await db.SaveChangesAsync(ct); return NoContent(); }
    [HttpGet("times/{id:int}/logo")] public async Task<IActionResult> Logo(int id, CancellationToken ct) { var t = await db.Times.FindAsync([id], ct); return t?.Logo == null ? NotFound() : File(t.Logo, t.LogoTipo ?? "image/png"); }
    [HttpPost("times/{timeId:int}/jogadores")] public async Task<IActionResult> Jogador(int timeId, JogadorInput r, CancellationToken ct) { if (!await db.Times.AnyAsync(x => x.Id == timeId, ct)) return NotFound(); if (string.IsNullOrWhiteSpace(r.Nome) || r.NumeroCamisa is < 0 or > 99 || !Enum.IsDefined(r.Posicao)) return BadRequest("Dados inválidos."); if (await db.Jogadores.CountAsync(x => x.TimeId == timeId, ct) >= 12) return Conflict("Limite de 12 jogadores atingido."); if (await db.Jogadores.AnyAsync(x => x.NomeNormalizado == N(r.Nome), ct)) return Conflict("Jogador já está em um time."); if (await db.Jogadores.AnyAsync(x => x.TimeId == timeId && x.NumeroCamisa == r.NumeroCamisa, ct)) return Conflict("Camisa já utilizada."); var j = new Jogador { TimeId = timeId, Nome = r.Nome.Trim(), NomeNormalizado = N(r.Nome), NumeroCamisa = (byte)r.NumeroCamisa, Posicao = r.Posicao }; db.Add(j); await db.SaveChangesAsync(ct); return Created($"/api/jogadores/{j.Id}", j); }
    [HttpPut("jogadores/{id:int}")] public async Task<IActionResult> EditarJogador(int id, JogadorInput r, CancellationToken ct) { var j = await db.Jogadores.FindAsync([id], ct); if (j == null) return NotFound(); if (string.IsNullOrWhiteSpace(r.Nome) || r.NumeroCamisa is < 0 or > 99 || !Enum.IsDefined(r.Posicao)) return BadRequest("Dados inválidos."); if (await db.Jogadores.AnyAsync(x => x.Id != id && (x.NomeNormalizado == N(r.Nome) || (x.TimeId == j.TimeId && x.NumeroCamisa == r.NumeroCamisa)), ct)) return Conflict("Nome ou camisa já utilizado."); j.Nome = r.Nome.Trim(); j.NomeNormalizado = N(r.Nome); j.NumeroCamisa = (byte)r.NumeroCamisa; j.Posicao = r.Posicao; await db.SaveChangesAsync(ct); return Ok(new { j.Id, j.Nome, j.NumeroCamisa, j.Posicao }); }
    [HttpDelete("jogadores/{id:int}")] public async Task<IActionResult> ExcluirJogador(int id, CancellationToken ct) { var j = await db.Jogadores.FindAsync([id], ct); if (j == null) return NotFound(); db.Remove(j); await db.SaveChangesAsync(ct); return NoContent(); }
    [HttpPost("partidas")] public async Task<IActionResult> Partida(PartidaInput r, CancellationToken ct) { if (r.TimeAId == r.TimeBId) return BadRequest("Selecione dois times diferentes."); if (r.TimeSacandoId != r.TimeAId && r.TimeSacandoId != r.TimeBId) return BadRequest("Escolha qual time começa sacando."); if (r.Fase is not ("Classificatória" or "Semifinal" or "Final")) return BadRequest("Fase inválida."); var equipes = await db.Times.Include(x => x.Jogadores).Where(x => x.Id == r.TimeAId || x.Id == r.TimeBId).ToListAsync(ct); if (equipes.Count != 2) return BadRequest("Time inválido."); try { var a = Montar42(equipes.Single(x => x.Id == r.TimeAId), r.TitularesTimeA); var b = Montar42(equipes.Single(x => x.Id == r.TimeBId), r.TitularesTimeB); var estado = new EstadoJogo { TimeSacandoId = r.TimeSacandoId, InicioUtc = DateTime.UtcNow, Fase = r.Fase }; var p = new Partida { TimeAId = r.TimeAId, TimeBId = r.TimeBId, EscalacaoTimeAJson = JsonSerializer.Serialize(a), EscalacaoTimeBJson = JsonSerializer.Serialize(b), EstadoJogoJson = JsonSerializer.Serialize(estado), Sets = [new() { Numero = 1 }] }; db.Add(p); await db.SaveChangesAsync(ct); return Created($"/api/partidas/{p.Id}", new { p.Id }); } catch (ArgumentException e) { return BadRequest(e.Message); } }
    [HttpGet("partidas/em-andamento")] public async Task<IActionResult> EmAndamento(CancellationToken ct) => Ok(await db.Partidas.AsNoTracking().Where(x => x.Status == StatusPartida.EmAndamento).OrderByDescending(x => x.Id).Select(x => new { x.Id, TimeA = new { x.TimeA.Id, x.TimeA.Nome, LogoUrl = x.TimeA.Logo == null ? null : $"/api/times/{x.TimeA.Id}/logo" }, TimeB = new { x.TimeB.Id, x.TimeB.Nome, LogoUrl = x.TimeB.Logo == null ? null : $"/api/times/{x.TimeB.Id}/logo" }, Set = x.Sets.Where(s => !s.Finalizado).Select(s => (int)s.Numero).FirstOrDefault() }).ToListAsync(ct));
    [HttpGet("partidas/{id:int}")] public async Task<IActionResult> ObterPartida(int id, CancellationToken ct) { var p = await db.Partidas.AsNoTracking().Include(x => x.TimeA).ThenInclude(x => x.Jogadores).Include(x => x.TimeB).ThenInclude(x => x.Jogadores).Include(x => x.Sets).SingleOrDefaultAsync(x => x.Id == id, ct); if (p == null) return NotFound(); var estado = PartidaService.Estado(p); return Ok(new { p.Id, p.TimeAId, TimeA = EquipePartida(p.TimeA, p.EscalacaoTimeAJson), p.TimeBId, TimeB = EquipePartida(p.TimeB, p.EscalacaoTimeBJson), p.Status, p.VencedorId, estado.RotacaoTimeA, estado.RotacaoTimeB, estado.TimeSacandoId, estado.InicioUtc, estado.FimUtc, estado.Fase, Pontos = estado.Pontos, Cartoes = estado.Cartoes, Substituicoes = JsonSerializer.Deserialize<List<SubstituicaoRegistro>>(p.SubstituicoesJson) ?? [], Sets = p.Sets.OrderBy(x => x.Numero).Select(x => new { x.Numero, x.PontosTimeA, x.PontosTimeB, x.Finalizado }) }); }
    [HttpGet("partidas/{id:int}/placar-publico")]
    public async Task<IActionResult> PlacarPublico(int id, CancellationToken ct)
    {
        Response.Headers.CacheControl = "no-store, no-cache, must-revalidate";
        var p = await db.Partidas.AsNoTracking().Include(x => x.TimeA).Include(x => x.TimeB).Include(x => x.Sets).SingleOrDefaultAsync(x => x.Id == id, ct);
        if (p == null) return NotFound();
        var estado = PartidaService.Estado(p);
        var atual = p.Sets.OrderBy(x => x.Numero).FirstOrDefault(x => !x.Finalizado) ?? p.Sets.OrderByDescending(x => x.Numero).FirstOrDefault();
        return Ok(new { p.Id, TimeA = new { p.TimeAId, p.TimeA.Nome, LogoUrl = p.TimeA.Logo == null ? null : $"/api/times/{p.TimeAId}/logo" }, TimeB = new { p.TimeBId, p.TimeB.Nome, LogoUrl = p.TimeB.Logo == null ? null : $"/api/times/{p.TimeBId}/logo" }, PontosTimeA = atual?.PontosTimeA ?? 0, PontosTimeB = atual?.PontosTimeB ?? 0, SetsTimeA = p.Sets.Count(x => x.Finalizado && x.PontosTimeA > x.PontosTimeB), SetsTimeB = p.Sets.Count(x => x.Finalizado && x.PontosTimeB > x.PontosTimeA), SetAtual = atual?.Numero ?? 0, p.Status, p.VencedorId, estado.TimeSacandoId, estado.Fase });
    }
    [HttpPost("partidas/{id:int}/substituicoes")] public async Task<IActionResult> Substituir(int id, SubstituicaoInput r, CancellationToken ct) { var p = await db.Partidas.Include(x => x.Sets).Include(x => x.TimeA).ThenInclude(x => x.Jogadores).Include(x => x.TimeB).ThenInclude(x => x.Jogadores).SingleOrDefaultAsync(x => x.Id == id, ct); if (p == null) return NotFound(); if (p.Status == StatusPartida.Finalizada) return Conflict("Partida finalizada."); var time = r.TimeId == p.TimeAId ? p.TimeA : r.TimeId == p.TimeBId ? p.TimeB : null; if (time == null) return BadRequest("Time inválido."); var ids = JsonSerializer.Deserialize<int[]>(r.TimeId == p.TimeAId ? p.EscalacaoTimeAJson : p.EscalacaoTimeBJson) ?? []; var zona = Array.IndexOf(ids, r.JogadorSaiId); var entra = time.Jogadores.SingleOrDefault(x => x.Id == r.JogadorEntraId); var sai = time.Jogadores.SingleOrDefault(x => x.Id == r.JogadorSaiId); if (zona < 0 || entra == null || sai == null || ids.Contains(entra.Id)) return BadRequest("Substituição inválida."); if (entra.Posicao != sai.Posicao) return BadRequest("A substituição deve manter a função 4x2."); ids[zona] = entra.Id; if (r.TimeId == p.TimeAId) p.EscalacaoTimeAJson = JsonSerializer.Serialize(ids); else p.EscalacaoTimeBJson = JsonSerializer.Serialize(ids); var set = p.Sets.Single(x => !x.Finalizado); var historico = JsonSerializer.Deserialize<List<SubstituicaoRegistro>>(p.SubstituicoesJson) ?? []; historico.Add(new(r.TimeId, sai.Id, sai.Nome, entra.Id, entra.Nome, set.Numero, set.PontosTimeA, set.PontosTimeB, DateTime.UtcNow)); p.SubstituicoesJson = JsonSerializer.Serialize(historico); await db.SaveChangesAsync(ct); return NoContent(); }
    [HttpPost("partidas/{id:int}/pontos")] public async Task<IActionResult> Ponto(int id, PontoInput r, CancellationToken ct) { try { var p = await placar.Alterar(id, r.TimeId, r.Delta, r.Tipo, r.JogadorId, ct); var estado = PartidaService.Estado(p); return Ok(new { p.Status, p.VencedorId, estado.RotacaoTimeA, estado.RotacaoTimeB, estado.TimeSacandoId, estado.FimUtc, Pontos = estado.Pontos, Cartoes = estado.Cartoes, Sets = p.Sets.OrderBy(x => x.Numero).Select(x => new { x.Numero, x.PontosTimeA, x.PontosTimeB, x.Finalizado }) }); } catch (KeyNotFoundException) { return NotFound(); } catch (InvalidOperationException e) { return Conflict(e.Message); } }
    [HttpPost("partidas/{id:int}/cartoes")] public async Task<IActionResult> Cartao(int id, CartaoInput r, CancellationToken ct) { try { var p = await placar.AplicarCartao(id, r.TimeId, r.JogadorId, r.Tipo, ct); return Ok(new { Cartoes = PartidaService.Estado(p).Cartoes }); } catch (KeyNotFoundException) { return NotFound(); } catch (InvalidOperationException e) { return Conflict(e.Message); } }
    [HttpGet("partidas/historico")] public async Task<IActionResult> ListarHistorico(CancellationToken ct) { var partidas = await db.Partidas.AsNoTracking().Include(x => x.TimeA).Include(x => x.TimeB).Include(x => x.Sets).Where(x => x.Status == StatusPartida.Finalizada).OrderByDescending(x => x.Id).ToListAsync(ct); return Ok(partidas.Select(p => { var estado = PartidaService.Estado(p); return new { p.Id, TimeA = p.TimeA.Nome, TimeB = p.TimeB.Nome, SetsTimeA = p.Sets.Count(x => x.Finalizado && x.PontosTimeA > x.PontosTimeB), SetsTimeB = p.Sets.Count(x => x.Finalizado && x.PontosTimeB > x.PontosTimeA), estado.Fase, estado.InicioUtc }; })); }
    [HttpPost("partidas/historico")] public async Task<IActionResult> Historico(HistoricoInput r, CancellationToken ct) { if (r.TimeAId == r.TimeBId || r.SetsTimeA is < 0 or > 3 || r.SetsTimeB is < 0 or > 3 || (r.SetsTimeA != 3 && r.SetsTimeB != 3) || (r.SetsTimeA == 3 && r.SetsTimeB == 3)) return BadRequest("Informe um resultado válido de melhor de 5."); if (await db.Times.CountAsync(x => x.Id == r.TimeAId || x.Id == r.TimeBId, ct) != 2) return BadRequest("Time inválido."); var sets = new List<SetPartida>(); for (byte i = 1; i <= r.SetsTimeA; i++) sets.Add(new() { Numero = (byte)(sets.Count + 1), PontosTimeA = 25, PontosTimeB = 20, Finalizado = true }); for (byte i = 1; i <= r.SetsTimeB; i++) sets.Add(new() { Numero = (byte)(sets.Count + 1), PontosTimeA = 20, PontosTimeB = 25, Finalizado = true }); var agora = DateTime.UtcNow; var p = new Partida { TimeAId = r.TimeAId, TimeBId = r.TimeBId, Status = StatusPartida.Finalizada, VencedorId = r.SetsTimeA == 3 ? r.TimeAId : r.TimeBId, EstadoJogoJson = JsonSerializer.Serialize(new EstadoJogo { InicioUtc = agora, FimUtc = agora, Fase = "Jogo anterior" }), Sets = sets }; db.Add(p); await db.SaveChangesAsync(ct); return Created($"/api/partidas/{p.Id}", new { p.Id }); }
    [HttpGet("times/{id:int}/rotacao")] public async Task<IActionResult> Rotacao(int id, CancellationToken ct) { var t = await db.Times.AsNoTracking().Include(x => x.Jogadores).SingleOrDefaultAsync(x => x.Id == id, ct); return t == null ? NotFound() : Ok(Escalacao(t)); }
    [HttpGet("classificacao")] public async Task<IActionResult> Classificacao(CancellationToken ct) { var times = await db.Times.AsNoTracking().ToListAsync(ct); var ps = await db.Partidas.AsNoTracking().Include(x => x.Sets).Where(x => x.Status == StatusPartida.Finalizada).ToListAsync(ct); return Ok(times.Select(t => { var jogos = ps.Where(p => p.TimeAId == t.Id || p.TimeBId == t.Id).ToList(); var sg = jogos.Sum(p => p.Sets.Count(s => s.Finalizado && ((p.TimeAId == t.Id && s.PontosTimeA > s.PontosTimeB) || (p.TimeBId == t.Id && s.PontosTimeB > s.PontosTimeA)))); var sp = jogos.Sum(p => p.Sets.Count(s => s.Finalizado)) - sg; var v = jogos.Count(p => p.VencedorId == t.Id); return new { t.Id, t.Nome, Jogos = jogos.Count, Vitorias = v, Derrotas = jogos.Count - v, SetsGanhos = sg, SetsPerdidos = sp, Pontos = v * 3 }; }).OrderByDescending(x => x.Pontos).ThenByDescending(x => x.SetsGanhos - x.SetsPerdidos).ThenBy(x => x.Nome)); }
    static int[] Montar42(Time t, int[] ids) { if (ids.Length != 6 || ids.Distinct().Count() != 6) throw new ArgumentException("Selecione exatamente 6 titulares diferentes por time."); var jogadores = t.Jogadores.Where(x => ids.Contains(x.Id)).ToList(); if (jogadores.Count != 6) throw new ArgumentException("A súmula contém jogador de outro time."); var levantadores = jogadores.Count(x => x.Posicao == Posicao.Levantador); var atacantes = jogadores.Count(x => x.Posicao == Posicao.Atacante); if (levantadores != 2 || atacantes != 4) throw new ArgumentException("O 4x2 exige 2 levantadores e 4 atacantes."); return ids; }
    static object EquipePartida(Time t, string json) { var ids = JsonSerializer.Deserialize<int[]>(json) ?? []; var titulares = ids.Select((id, i) => { var x = t.Jogadores.SingleOrDefault(j => j.Id == id); return new { Zona = i + 1, Id = x?.Id, Nome = x?.Nome, NumeroCamisa = x?.NumeroCamisa, Posicao = x?.Posicao.ToString() }; }).ToArray(); return new { t.Id, t.Nome, Jogadores = titulares, Reservas = t.Jogadores.Where(x => !ids.Contains(x.Id)).OrderBy(x => x.NumeroCamisa).Select(x => new { x.Id, x.Nome, x.NumeroCamisa, Posicao = x.Posicao.ToString() }).ToArray() }; }
    static object[] Escalacao(Time t) { var ids = t.Jogadores.Count >= 6 ? Montar42(t, t.Jogadores.Where(x => x.Posicao == Posicao.Levantador).Take(2).Concat(t.Jogadores.Where(x => x.Posicao == Posicao.Atacante).Take(4)).Select(x => x.Id).ToArray()) : []; return ids.Select((id, i) => { var x = t.Jogadores.Single(j => j.Id == id); return (object)new { Zona = i + 1, Funcao = i + 1 is 2 or 3 or 4 ? "Rede" : "Defesa", x.Id, x.Nome, x.NumeroCamisa, Posicao = x.Posicao.ToString() }; }).ToArray(); }
}
public record JogadorInput(string Nome, int NumeroCamisa, Posicao Posicao); public record PartidaInput(int TimeAId, int TimeBId, int[] TitularesTimeA, int[] TitularesTimeB, int TimeSacandoId, string Fase); public record PontoInput(int TimeId, int Delta, string? Tipo, int? JogadorId); public record CartaoInput(int TimeId, int JogadorId, string Tipo); public record HistoricoInput(int TimeAId, int TimeBId, int SetsTimeA, int SetsTimeB); public record SubstituicaoInput(int TimeId, int JogadorSaiId, int JogadorEntraId); public record SubstituicaoRegistro(int TimeId, int JogadorSaiId, string JogadorSai, int JogadorEntraId, string JogadorEntra, byte Set, int PontosTimeA, int PontosTimeB, DateTime DataUtc);
